// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.math;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.within;

import java.math.BigDecimal;
import java.math.BigInteger;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.MATHF;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.function.math.xpath.XPathSqrt;
import org.junit.jupiter.api.Test;

class MathFunctionsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static Literal lit(String lexical, CoreDatatype.XSD datatype) {
		return VF.createLiteral(lexical, datatype);
	}

	private static double dbl(Value v) {
		assertThat(((Literal) v).getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		return ((Literal) v).doubleValue();
	}

	@Test
	void unaryFunctionsReturnDoubles() {
		assertThat(dbl(new Sqrt().evaluate(VF, VF.createLiteral(16)))).isEqualTo(4.0);
		assertThat(dbl(new Cbrt().evaluate(VF, VF.createLiteral(27)))).isEqualTo(3.0);
		assertThat(dbl(new Exp().evaluate(VF, VF.createLiteral(1)))).isCloseTo(Math.E, within(1e-12));
		assertThat(dbl(new Ln().evaluate(VF, VF.createLiteral(Math.E)))).isCloseTo(1.0, within(1e-12));
		assertThat(dbl(new Log10().evaluate(VF, VF.createLiteral(1000)))).isCloseTo(3.0, within(1e-12));
		assertThat(dbl(new Log2().evaluate(VF, VF.createLiteral(8)))).isCloseTo(3.0, within(1e-12));
		assertThat(dbl(new Sin().evaluate(VF, VF.createLiteral(0)))).isEqualTo(0.0);
		assertThat(dbl(new Cos().evaluate(VF, VF.createLiteral(0)))).isEqualTo(1.0);
		assertThat(dbl(new Tan().evaluate(VF, VF.createLiteral(0)))).isEqualTo(0.0);
		assertThat(dbl(new Asin().evaluate(VF, VF.createLiteral(1)))).isCloseTo(Math.PI / 2, within(1e-12));
		assertThat(dbl(new Acos().evaluate(VF, VF.createLiteral(1)))).isEqualTo(0.0);
		assertThat(dbl(new Atan().evaluate(VF, VF.createLiteral(1)))).isCloseTo(Math.PI / 4, within(1e-12));
		assertThat(dbl(new Atan2().evaluate(VF, VF.createLiteral(1), VF.createLiteral(1))))
				.isCloseTo(Math.PI / 4, within(1e-12));
		assertThat(dbl(new Hypot().evaluate(VF, VF.createLiteral(3), VF.createLiteral(4)))).isEqualTo(5.0);
		assertThat(dbl(new Pow().evaluate(VF, VF.createLiteral(2), VF.createLiteral(10)))).isEqualTo(1024.0);
		assertThat(dbl(new Pi().evaluate(VF))).isEqualTo(Math.PI);
		assertThat(dbl(new Sqrt().evaluate(VF, lit("2.25", CoreDatatype.XSD.DECIMAL)))).isEqualTo(1.5);
	}

	@Test
	void sqrtOfNegativeIsNaNLikeXPath() {
		assertThat(dbl(new Sqrt().evaluate(VF, VF.createLiteral(-1)))).isNaN();
	}

	@Test
	void nonNumericArgumentIsAnError() {
		assertThatThrownBy(() -> new Sqrt().evaluate(VF, VF.createLiteral("x")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Sqrt().evaluate(VF, VF.createIRI("urn:x")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Sqrt().evaluate(VF)).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void signReturnsInteger() {
		assertThat(new Sign().evaluate(VF, VF.createLiteral(-7.5)))
				.isEqualTo(VF.createLiteral(BigInteger.ONE.negate()));
		assertThat(new Sign().evaluate(VF, lit("0.0", CoreDatatype.XSD.DECIMAL)))
				.isEqualTo(VF.createLiteral(BigInteger.ZERO));
		assertThat(new Sign().evaluate(VF, VF.createLiteral(new BigInteger("99999999999999999999"))))
				.isEqualTo(VF.createLiteral(BigInteger.ONE));
	}

	@Test
	void roundAndTruncKeepArgumentDatatype() {
		assertThat(new Round().evaluate(VF, lit("2.345", CoreDatatype.XSD.DECIMAL), VF.createLiteral(2)))
				.isEqualTo(lit("2.35", CoreDatatype.XSD.DECIMAL));
		assertThat(new Round().evaluate(VF, lit("-2.5", CoreDatatype.XSD.DECIMAL)))
				.isEqualTo(lit("-2", CoreDatatype.XSD.DECIMAL));
		assertThat(new Round().evaluate(VF, lit("2.5", CoreDatatype.XSD.DECIMAL)))
				.isEqualTo(lit("3", CoreDatatype.XSD.DECIMAL));
		assertThat(new Round().evaluate(VF, VF.createLiteral(1234), VF.createLiteral(-2)))
				.isEqualTo(VF.createLiteral(new BigInteger("1200")));
		assertThat(new Round().evaluate(VF, VF.createLiteral(1250), VF.createLiteral(-2)))
				.isEqualTo(VF.createLiteral(new BigInteger("1300")));
		assertThat(new Round().evaluate(VF, VF.createLiteral(7), VF.createLiteral(3))).isEqualTo(VF.createLiteral(7));
		assertThat(new Trunc().evaluate(VF, lit("2.789", CoreDatatype.XSD.DECIMAL), VF.createLiteral(1)))
				.isEqualTo(lit("2.7", CoreDatatype.XSD.DECIMAL));
		assertThat(new Trunc().evaluate(VF, lit("-2.789", CoreDatatype.XSD.DECIMAL)))
				.isEqualTo(lit("-2", CoreDatatype.XSD.DECIMAL));
		assertThat(dbl(new Trunc().evaluate(VF, VF.createLiteral(3.99)))).isEqualTo(3.0);
		assertThat(dbl(new Round().evaluate(VF, VF.createLiteral(2.675), VF.createLiteral(2)))).isEqualTo(2.68);
		Literal nan = VF.createLiteral(Double.NaN);
		assertThat(new Round().evaluate(VF, nan)).isEqualTo(nan);
	}

	@Test
	void modFollowsNumericPromotion() {
		assertThat(new Mod().evaluate(VF, VF.createLiteral(10), VF.createLiteral(3)))
				.isEqualTo(VF.createLiteral(BigInteger.ONE));
		assertThat(new Mod().evaluate(VF, VF.createLiteral(-10), VF.createLiteral(3)))
				.isEqualTo(VF.createLiteral(BigInteger.ONE.negate()));
		assertThat(new Mod().evaluate(VF, lit("10.5", CoreDatatype.XSD.DECIMAL), VF.createLiteral(3)))
				.isEqualTo(VF.createLiteral(new BigDecimal("1.5")));
		assertThat(dbl(new Mod().evaluate(VF, VF.createLiteral(10.5), VF.createLiteral(3)))).isEqualTo(1.5);
		assertThatThrownBy(() -> new Mod().evaluate(VF, VF.createLiteral(10), VF.createLiteral(0)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(dbl(new Mod().evaluate(VF, VF.createLiteral(10.0), VF.createLiteral(0)))).isNaN();
	}

	@Test
	void greatestAndLeastUseSparqlOrdering() {
		Value greatest = new Greatest().evaluate(VF, VF.createLiteral(1), lit("2.5", CoreDatatype.XSD.DECIMAL),
				VF.createLiteral(2.0));
		assertThat(greatest).isEqualTo(lit("2.5", CoreDatatype.XSD.DECIMAL));
		Value least = new Least().evaluate(VF, VF.createLiteral(1), lit("2.5", CoreDatatype.XSD.DECIMAL),
				VF.createLiteral(-2.0));
		assertThat(least).isEqualTo(VF.createLiteral(-2.0));
		assertThat(new Greatest().evaluate(VF, VF.createLiteral("b"), VF.createLiteral("a")))
				.isEqualTo(VF.createLiteral("b"));
		assertThatThrownBy(() -> new Greatest().evaluate(VF)).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void decimalFormatUsesRootLocaleByDefault() {
		assertThat(new DecimalFormat().evaluate(VF, VF.createLiteral(1234567.891), VF.createLiteral("#,##0.00")))
				.isEqualTo(VF.createLiteral("1,234,567.89"));
		assertThat(new DecimalFormat().evaluate(VF, VF.createLiteral(1234567.891), VF.createLiteral("#,##0.00"),
				VF.createLiteral("de"))).isEqualTo(VF.createLiteral("1.234.567,89"));
		assertThat(new DecimalFormat().evaluate(VF, lit("0.5", CoreDatatype.XSD.DECIMAL), VF.createLiteral("0.0%")))
				.isEqualTo(VF.createLiteral("50.0%"));
		assertThatThrownBy(() -> new DecimalFormat().evaluate(VF, VF.createLiteral(1), VF.createLiteral("#,##0.#.#")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void allMathFunctionsAreRegisteredAndDeterministic() {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		for (String name : new String[] { "sqrt", "cbrt", "pow", "exp", "ln", "log10", "log2", "sin", "cos", "tan",
				"asin", "acos", "atan", "atan2", "hypot", "sign", "trunc", "round", "mod", "greatest", "least", "pi",
				"decimalFormat" }) {
			Function function = registry.get(MATHF.NAMESPACE + name).orElse(null);
			assertThat(function).as(name).isNotNull();
			assertThat(function.getDeterminism()).as(name).isEqualTo(Function.Determinism.DETERMINISTIC);
		}
		for (String name : new String[] { "sqrt", "pow", "exp", "exp10", "log", "log10", "sin", "cos", "tan", "asin",
				"acos", "atan", "atan2", "pi" }) {
			assertThat(registry.get(MATHF.XPATH_MATH_NAMESPACE + name)).as(name).isPresent();
		}
		assertThat(new XPathSqrt().getURI()).isEqualTo("http://www.w3.org/2005/xpath-functions/math#sqrt");
	}
}
